package com.tnr.cityguide.admin;
import com.tnr.cityguide.city.*;import com.tnr.cityguide.common.NotFoundException;import com.tnr.cityguide.place.PlaceRepository;import com.tnr.cityguide.storage.StorageService;import io.swagger.v3.oas.annotations.tags.Tag;import java.time.ZoneId;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/admin/cities") @Tag(name="Admin cities") public class AdminCityController {
 private static final Logger log=LoggerFactory.getLogger(AdminCityController.class);
 private final CityRepository cities;private final PlaceRepository places;private final StorageService storage;
 public AdminCityController(CityRepository c,PlaceRepository p,StorageService s){cities=c;places=p;storage=s;}
 public record CityRequest(String id,String name,String country,double lat,double lng,String timezone,Integer hue,String blurb,String description,String imageUrl){}
 @PostMapping @Transactional public ResponseEntity<CityService.CityDto> create(@RequestBody CityRequest r){log.info("[ADMIN_CITY] Create requested: cityId={}, name={}",r.id(),r.name());if(r.id()==null||cities.existsById(r.id()))throw new ResponseStatusException(HttpStatus.CONFLICT,"City already exists.");City c=map(r,new City(),r.id());cities.save(c);return ResponseEntity.status(201).body(dto(c));}
 @PutMapping("/{id}") @Transactional public CityService.CityDto update(@PathVariable String id,@RequestBody CityRequest r){log.info("[ADMIN_CITY] Update requested: cityId={}",id);City c=cities.findById(id).orElseThrow(()->new NotFoundException("City not found."));return dto(cities.save(map(r,c,id)));}
 @PostMapping("/{id}/image") @Transactional public CityService.CityDto uploadImage(@PathVariable String id,@RequestPart("file")MultipartFile file){log.info("[ADMIN_CITY] Image upload requested: cityId={}, filename={}, sizeBytes={}",id,file.getOriginalFilename(),file.getSize());City c=cities.findById(id).orElseThrow(()->new NotFoundException("City not found."));StorageService.StoredImage image=storage.store("cities/"+id,file,8L*1024*1024);String old=c.getImagePublicId();c.setImageUrl(image.url());c.setImagePublicId(image.publicId());cities.save(c);deleteAfterCommit(old);return dto(c);}
 @DeleteMapping("/{id}/image") @Transactional public ResponseEntity<Void> deleteImage(@PathVariable String id){log.info("[ADMIN_CITY] Image removal requested: cityId={}",id);City c=cities.findById(id).orElseThrow(()->new NotFoundException("City not found."));String old=c.getImagePublicId();c.setImageUrl(null);c.setImagePublicId(null);cities.save(c);deleteAfterCommit(old);return ResponseEntity.noContent().build();}
 @DeleteMapping("/{id}") @Transactional public ResponseEntity<Void> delete(@PathVariable String id){log.info("[ADMIN_CITY] Delete requested: cityId={}",id);City c=cities.findById(id).orElseThrow(()->new NotFoundException("City not found."));if(places.countByCityId(id)>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"This city still has places. Delete or move them first.");deleteAfterCommit(c.getImagePublicId());cities.delete(c);return ResponseEntity.noContent().build();}
 private void deleteAfterCommit(String id){if(id==null||id.isBlank())return;if(org.springframework.transaction.support.TransactionSynchronizationManager.isSynchronizationActive())org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){@Override public void afterCommit(){storage.delete(id);}});}
 private City map(CityRequest r,City c,String id){try{ZoneId.of(r.timezone());}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid timezone.");}c.setId(id);c.setName(r.name());c.setCountry(r.country());c.setLat(r.lat());c.setLng(r.lng());c.setTimezone(r.timezone());c.setHue(r.hue()==null?200:r.hue());c.setBlurb(r.blurb());c.setDescription(r.description());if(r.imageUrl()!=null&&!r.imageUrl().equals(c.getImageUrl())){c.setImageUrl(r.imageUrl());c.setImagePublicId(null);}return c;}
 private CityService.CityDto dto(City c){return new CityService.CityDto(c.getId(),c.getName(),c.getCountry(),c.getLat(),c.getLng(),c.getTimezone(),c.getHue(),c.getBlurb(),c.getDescription(),c.getImageUrl(),places.countByCityId(c.getId()));}
}